<?php
require __DIR__.'/bootstrap.php';require_auth();if(!can('products.view')){http_response_code(403);exit('Forbidden');}require __DIR__.'/partials.php';
if($_SERVER['REQUEST_METHOD']==='POST'&&can('products.manage')){verify_csrf();$cost=max(0,(float)$_POST['avg_cost']);$opening=max(0,(float)$_POST['opening_stock']);$data=[trim($_POST['item_code']),trim($_POST['name']),($_POST['barcode']??'')?:null,($_POST['brand_id']??'')?:null,(int)$_POST['category_id'],trim($_POST['model']??''),trim($_POST['unit']??'PCS')?:'PCS',$cost,(float)$_POST['retail_price'],(float)$_POST['wholesale_price'],(float)($_POST['minimum_stock']??0),isset($_POST['serial_tracking'])?1:0,$opening];$db->beginTransaction();try{$stmt=$db->prepare('INSERT INTO products(item_code,name,barcode,brand_id,category_id,model,unit,avg_cost,retail_price,wholesale_price,minimum_stock,serial_tracking,current_stock,warranty_months,rack_location) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,0,NULL)');$stmt->execute($data);$id=(int)$db->lastInsertId();if($opening>0)$db->prepare('INSERT INTO stock_movements(product_id,movement_type,quantity,unit_cost,running_quantity,reference_type,reference_id,notes,created_by) VALUES(?,"opening",?,?,?,"product",?,"Starting stock entered when product was created",?)')->execute([$id,$opening,$cost,$opening,$id,user()['id']]);audit($db,'create','product',$id,null,['item_code'=>$data[0],'name'=>$data[1],'buying_price'=>$cost,'starting_stock'=>$opening]);$db->commit();flash('success','Product and starting stock saved.');}catch(Throwable $e){$db->rollBack();flash('danger','Item code or barcode already exists. Please check and try again.');}redirect('products.php');}
$q=trim($_GET['q']??'');$like="%$q%";$stmt=$db->prepare('SELECT p.*,c.name category FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.status="active" AND (p.name LIKE ? OR p.item_code LIKE ? OR p.barcode LIKE ?) ORDER BY p.id DESC');$stmt->execute([$like,$like,$like]);$rows=$stmt->fetchAll();$brands=$db->query('SELECT * FROM brands WHERE status="active" ORDER BY name')->fetchAll();$categories=$db->query('SELECT * FROM categories WHERE status="active" ORDER BY name')->fetchAll();page_start('Products','products.php');?>
<style>.simple-fields{display:grid;gap:14px}.price-stock-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.cost-note{background:#fff7dd;border-left:4px solid #d5a02d;padding:11px;border-radius:6px;font-size:12px;color:#684d17}.optional-fields{margin:16px 0;border:1px solid #e3e8e2;border-radius:10px;background:#f8faf7}.optional-fields summary{padding:13px 15px;cursor:pointer;font-weight:700;color:#174e39}.optional-fields[open] summary{border-bottom:1px solid #e3e8e2}.optional-fields .form-grid{padding:15px}</style><section class="action-banner"><div><span class="step-number">1</span><div><b>Create product and enter its starting stock</b><p>Future stock purchases must be entered through Stock & Purchases so buying cost stays accurate.</p></div></div></section><div class="toolbar"><form><input name="q" value="<?=e($q)?>" placeholder="Search product"><button class="btn secondary">Search</button></form><?php if(can('products.manage')):?><button class="btn primary" onclick="document.getElementById('product-form').scrollIntoView({behavior:'smooth'})">+ Add Product</button><?php endif;?></div><div class="page-grid"><section class="panel table-panel"><div class="panel-head"><div><span class="eyebrow">Product list</span><h3><?=count($rows)?> products</h3></div></div><div class="table-wrap"><table><thead><tr><th>Code & Product</th><th>Category</th><th>In Stock</th><?php if(user()['role_code']!=='cashier'):?><th>Buying Cost</th><?php endif;?><th>Retail</th><th>Wholesale</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6"><div class="empty-state compact"><b>No products yet</b><span>Use the form on the right.</span></div></td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><b><?=e($r['item_code'])?></b><br><span class="muted"><?=e($r['name'])?></span></td><td><?=e($r['category']??'—')?></td><td><span class="status <?=$r['current_stock']<=$r['minimum_stock']?'overdue':'active'?>"><?=e($r['current_stock'])?> <?=e($r['unit'])?></span></td><?php if(user()['role_code']!=='cashier'):?><td><b><?=money($r['avg_cost'])?></b></td><?php endif;?><td><?=money($r['retail_price'])?></td><td><?=money($r['wholesale_price'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php if(can('products.manage')):?><aside class="panel" id="product-form"><div class="panel-head"><div><span class="eyebrow">New product</span><h3>Add Product</h3></div></div><form method="post"><input type="hidden" name="_csrf" value="<?=csrf()?>"><div class="simple-fields"><label>Item code<input name="item_code" placeholder="Example: TV-001" required></label><label>Product name<input name="name" required></label><label>Category<select name="category_id" required><option value="">Choose category</option><?php foreach($categories as $v):?><option value="<?=$v['id']?>"><?=e($v['name'])?></option><?php endforeach;?></select></label><div class="price-stock-grid"><label>Buying price<input type="number" step=".01" min="0" name="avg_cost" required></label><label>Starting stock quantity<input type="number" step=".001" min="0" name="opening_stock" value="0" required></label><label>Retail selling price<input type="number" step=".01" min="0" name="retail_price" required></label><label>Wholesale selling price<input type="number" step=".01" min="0" name="wholesale_price" required></label></div><div class="cost-note"><b>Buying price is inventory cost.</b> It becomes product cost only when the item is sold. Rent, salaries and electricity belong under Expenses.</div></div><details class="optional-fields"><summary>More product details (optional)</summary><div class="form-grid"><label>Barcode<input name="barcode"></label><label>Brand<select name="brand_id"><option value="">Choose</option><?php foreach($brands as $v):?><option value="<?=$v['id']?>"><?=e($v['name'])?></option><?php endforeach;?></select></label><label>Model<input name="model"></label><label>Unit<input name="unit" value="PCS"></label><label>Low-stock warning<input type="number" step=".001" min="0" name="minimum_stock" value="0"></label><label><span><input type="checkbox" name="serial_tracking"> Track serial numbers</span></label></div></details><button class="btn primary wide">Save Product & Stock</button></form></aside><?php endif;?></div><?php page_end();
